     * 1. The folder is flipped to status='deleting'. 2. All contained documents are flipped to
     * status='deleting' and each is dispatched as a kb_delete_file job. 3. A single
     * kb_delete_folder_finalize job is published; the worker polls for document drain, then deletes
     * the Vertex AI corpus and the folder row.
     *
     * System folders cannot be deleted.
     *
     * Scopes: knowledge_base:delete.
     *
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/Knowledge%20Base/delete_folder_api_v1_knowledge_base_folders__folder_id__delete
     */
    public function deleteFolder(string $folderId): FolderDelete
    {
        $response = $this->connector->send(new Request(
            Method::Delete,
            '/knowledge-base/folders/'.Payload::segment($folderId),
        ));

        return FolderDelete::fromArray($response->data());
    }

    /**
     * Retry Failed Documents In Folder.
     *
     * Retry every failed document in a folder.
     *
     * Re-queues every retryable document in the folder using the same per-document logic as the single
     * retry endpoint: all status='failed' documents, plus any status='pending_ingestion' document that
     * is *stuck* — left un-imported under a crawl/ingestion job that has since finished (see
     * _pending_ingestion_is_stuck). A pending_ingestion row still owned by a running job is skipped,
     * never re-queued. A folder with nothing to retry is not an error — it returns retried_count: 0.
     *
     * Returns {"success": true, "retried_count": N}.
     *
     * Scopes: knowledge_base:create.
     *
     * @param  ?string  $idempotencyKey  Repeat a request safely: SendSeven answers a repeat with the first result. One is generated when omitted.
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/Knowledge%20Base/retry_failed_documents_in_folder_api_v1_knowledge_base_folders__folder_id__retry_failed_post
     */
    public function retryFailedDocumentsInFolder(string $folderId, ?string $idempotencyKey = null): RetryFailed
    {
        $response = $this->connector->send(new Request(
            Method::Post,
            '/knowledge-base/folders/'.Payload::segment($folderId).'/retry-failed',
            headers: $idempotencyKey === null ? [] : ['Idempotency-Key' => $idempotencyKey],
        ));

        return RetryFailed::fromArray($response->data());
    }

    /**
     * Get Kb Job Status.
     *
     * Poll the status of a KB admin job (upload, delete, folder delete).
     *
     * A job_id can belong to either a document operation (uploaded or deletion) or a folder deletion.
     * The returned resource_type tells the client which. Returns 404 if no resource carries this
     * job_id.
     *
     * Scopes: knowledge_base:read.
     *
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/Knowledge%20Base/get_kb_job_status_api_v1_knowledge_base_jobs__job_id__get
     */
    public function getKbJobStatus(string $jobId): JobStatus
    {
        $response = $this->connector->send(new Request(
            Method::Get,
            '/knowledge-base/jobs/'.Payload::segment($jobId),
        ));

        return JobStatus::fromArray($response->data());
    }

    /**
     * Search Knowledge Base.
     *
     * Search the knowledge base using Vertex AI RAG.
     *
     * Requires AI Features: This endpoint requires AI features to be enabled in the billing account
     * settings.
     *
     * Returns AI-generated answer with citations and sources.
     *
     * Scopes: knowledge_base:read.
     *
     * @param  string  $query  Search query text
     * @param  list<string>|null  $documentTypes  Filter by document types (not currently used with RAG retrieval)
     * @param  ?string  $folderId  Optional folder ID to scope search to a specific folder. When provided, only documents in that folder are searched.
     * @param  ?int  $limit  Maximum number of sources to return
     * @param  ?string  $idempotencyKey  Repeat a request safely: SendSeven answers a repeat with the first result. One is generated when omitted.
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/Knowledge%20Base/search_knowledge_base_api_v1_knowledge_base_search_post
     */
    public function search(string $query, ?array $documentTypes = null, ?string $folderId = null, ?int $limit = null, ?string $idempotencyKey = null): SearchKnowledge
    {
        $response = $this->connector->send(new Request(
            Method::Post,
            '/knowledge-base/search',
            body: Payload::body(['query' => $query, 'document_types' => $documentTypes, 'folder_id' => $folderId, 'limit' => $limit]),
            headers: $idempotencyKey === null ? [] : ['Idempotency-Key' => $idempotencyKey],
        ));

        return SearchKnowledge::fromArray($response->data());
    }

    /**
     * List Ticket Summaries.
     *
     * List all conversation summaries stored in the knowledge base.
     *
     * Returns conversations that have been AI-summarized.
     *
     * Scopes: knowledge_base:read.
     *
     * @param  ?int  $page  Page number (1-indexed)
     * @param  ?int  $pageSize  Items per page
     * @return Page<TicketSummary>
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/Knowledge%20Base/list_ticket_summaries_api_v1_knowledge_base_tickets_get
     */
    public function listTicketSummaries(?int $page = null, ?int $pageSize = null): Page
    {
        $response = $this->connector->send(new Request(
            Method::Get,
            '/knowledge-base/tickets',
            query: Payload::query(['page' => $page, 'page_size' => $pageSize]),
        ));

        return Hydrate::page($response->data(), TicketSummary::fromArray(...), fn (int $page): Page => $this->listTicketSummaries(page: $page, pageSize: $pageSize));
    }

    /**
     * Delete Ticket From Kb.
     *
     * Remove a conversation/ticket summary from the knowledge base.
     *
     * The ticket_id parameter can be either a conversation ID (new) or legacy ticket ID. This removes
     * the document from Vertex AI RAG Corpus and clears the gemini_document_name field.
     *
     * Scopes: knowledge_base:delete.
     *
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/Knowledge%20Base/delete_ticket_from_kb_api_v1_knowledge_base_tickets__ticket_id__delete
     */
    public function deleteTicketFromKb(string $ticketId): KnowledgeBaseDelete
    {
        $response = $this->connector->send(new Request(
            Method::Delete,
            '/knowledge-base/tickets/'.Payload::segment($ticketId),
        ));

        return KnowledgeBaseDelete::fromArray($response->data());
    }
}
